const crypto = require('crypto');
const fail = (statusCode, error) => [{ json: { authorized: false, statusCode, error } }];
const authorization = $json.headers?.authorization ?? '';
if (!authorization.startsWith('Bearer ')) return fail(401, 'Sesión requerida.');
const secret = $env.JWT_SECRET;
if (!secret) return fail(500, 'JWT_SECRET no está configurado.');
try {
 const token = authorization.slice(7).trim(); const [h,p,s,x] = token.split('.'); if (!h || !p || !s || x) throw new Error();
 const expected = crypto.createHmac('sha256', secret).update(`${h}.${p}`).digest('base64url'); const left=Buffer.from(s); const right=Buffer.from(expected); if(left.length!==right.length || !crypto.timingSafeEqual(left,right)) throw new Error();
 const payload=JSON.parse(Buffer.from(p,'base64url').toString('utf8')); if(!payload.exp || payload.exp<=Math.floor(Date.now()/1000)) throw new Error();
 const role=String(payload.rol ?? payload.role ?? '').toUpperCase(); const permissions=(Array.isArray(payload.permisos)?payload.permisos:[]).map(v=>String(v).toLowerCase());
 if(role!=='ADMINISTRADOR_PARKING' && !permissions.includes('parqueadero.ver') && !permissions.includes('parqueadero.gestionar')) return fail(403,'No tiene permisos para consultar parqueadero.');
 return [{json:{authorized:true}}];
} catch { return fail(401,'La sesión es inválida o ha vencido.'); }
